#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <stdint.h>
#include <pthread.h>
#include <termios.h>
#include <unistd.h>
#include <stdbool.h>
#define MAP_W 8
#define MAP_H 8
typedef struct{int8_t x;int8_t y;} POINT;typedef struct{pthread_mutex_t mutex;uint8_t dir;uint8_t move;bool run;bool game_over;bool restart;} MUTEX_DIR;POINT rand_point(POINT*snake,int snake_tail){POINT p=(POINT){rand()%MAP_W,rand()%MAP_H};for(int i=0;i<snake_tail;++i) if(snake[i].x==p.x&&snake[i].y==p.y){p=(POINT){rand()%MAP_W,rand()%MAP_H};i=-1;} return p;} void enable_raw_mode(){struct termios term;tcgetattr(STDIN_FILENO,&term);term.c_lflag&=~(ICANON|ECHO);tcsetattr(STDIN_FILENO,TCSANOW,&term);} void*key_handler(void*p){enable_raw_mode();MUTEX_DIR*md=p;while(md->run){char c;read(STDIN_FILENO,&c,1);pthread_mutex_lock(&md->mutex);if(c=='q'||c=='Q'){md->run=false;} else if(md->game_over){if(c=='r'||c=='R') md->restart=true;} else if((c=='a'||c=='A')&&md->move!=2){md->dir=1;} else if((c=='d'||c=='D')&&md->move!=1){md->dir=2;} else if((c=='w'||c=='W')&&md->move!=4){md->dir=3;} else if((c=='s'||c=='S')&&md->move!=3){md->dir=4;} pthread_mutex_unlock(&md->mutex);} return NULL;} int main(){srand(time(NULL));char apple_ascii[7]="\e[41m  ";char back_ascii[7]="\e[47m  ";char snake_ascii[7]="\e[42m  ";MUTEX_DIR md;const struct timespec sleep_time={.tv_sec=0,.tv_nsec=250*1000000};pthread_t key_handler_thread;uint8_t snake_tail=1;POINT*snake=calloc(MAP_W*MAP_H,sizeof(POINT));POINT apple=rand_point(snake,snake_tail);int out_size=MAP_H*(MAP_W*7+1)+1;char*out=calloc(out_size,sizeof(char));snake[0]=(POINT){1,1};md.run=true;md.game_over=false;md.restart=false;md.dir=0;md.move=0;if(pthread_mutex_init(&md.mutex,NULL)!=0){printf("Mutex initialization error. Exiting.\n");free(out);free(snake);return-1;} else if(pthread_create(&key_handler_thread,NULL,key_handler,&md)!=0){printf("Thread initialization error. Exiting.\n");free(out);free(snake);return-1;} pthread_detach(key_handler_thread);while(md.run){if(md.game_over){if(md.restart){snake[0]=(POINT){1,1};snake_tail=1;apple=rand_point(snake,snake_tail);md.dir=0;md.move=0;md.game_over=false;md.restart=false;} goto draw;} POINT new_head=snake[0];new_head.x+=md.dir==1?-1:md.dir==2?1:0;new_head.y+=md.dir==3?-1:md.dir==4?1:0;if(new_head.x<0) new_head.x=MAP_W-1;else if(new_head.x>=MAP_W) new_head.x=0;if(new_head.y<0) new_head.y=MAP_H-1;else if(new_head.y>=MAP_H) new_head.y=0;if(new_head.x==apple.x&&new_head.y==apple.y){snake_tail++;apple=rand_point(snake,snake_tail);} for(int i=snake_tail-1;i>0;--i){snake[i]=snake[i-1];if(snake[i].x==new_head.x&&snake[i].y==new_head.y) md.game_over=true;} snake[0]=new_head;md.move=md.dir;draw:for(int8_t j=0;j<MAP_H;++j){for(int8_t i=0;i<=MAP_W;++i){strncpy(out+(i*7+j*(MAP_W*7+1)),back_ascii,7);} out[MAP_W*7+j*(MAP_W*7+1)]='\n';} out[MAP_H*(MAP_W*7+1)]='\0';strncpy(out+apple.x*7+apple.y*(MAP_W*7+1),apple_ascii,7);for(int i=0;i<snake_tail;++i) strncpy(out+snake[i].x*7+snake[i].y*(MAP_W*7+1),snake_ascii,7);printf("\e[2J\e[H");printf("\e[7m -- CNake (C-snake) by justfollowyourdreams -- \e[0m\n");printf(md.dir==0?"\t(WASD to move, Q to exit)\n":md.game_over?"Game over! Score: %d. Press R to restart, Q to exit.\n":"Score: %d\n",snake_tail-1);printf("%s\e[0m",out);fflush(stdout);nanosleep(&sleep_time,NULL);} free(out);free(snake);pthread_mutex_destroy(&md.mutex);pthread_join(key_handler_thread,NULL);return 0;}